    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yazılım Borsası V7</title>
<style>
:root{color-scheme:dark;--bg:#030711;--p:#0a1424;--p2:#101e33;--l:#263b59;--t:#eff6ff;--m:#91a8c5;--g:#42e1a0;--b:#62a8ff;--r:#ff6b7d;--y:#ffd166;--v:#b78cff;--c:#42d6ee;--s:0 16px 50px #0009}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#12315c 0,transparent 32%),radial-gradient(circle at 92% 0,#321a59 0,transparent 28%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.shell{max-width:2300px;margin:auto}.top{position:sticky;top:5px;z-index:40;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 15px;border:1px solid var(--l);border-radius:16px;background:#081322ef;box-shadow:var(--s)}.brand{font-weight:1000;font-size:20px}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px;font-weight:500}.status,.tabs,.tags,.row,.legend{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.status{justify-content:flex-end}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.ticker{overflow:hidden;border:1px solid #7b6028;background:linear-gradient(90deg,#21170b,#181224,#21170b);border-radius:11px;margin:10px 0;white-space:nowrap}.tickerTrack{display:inline-block;padding:9px 0;animation:ticker 42s linear infinite;font-size:10px;font-weight:850;color:var(--y)}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.tabs{margin:11px 0}.tab{cursor:pointer;padding:9px 12px;border:1px solid var(--l);border-radius:999px;background:#091525;color:var(--m);font-weight:900}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c;border-color:transparent}.page[hidden]{display:none!important}.page:not([hidden]){display:grid;gap:11px}.kpis{display:grid;grid-template-columns:repeat(10,minmax(120px,1fr));gap:8px}.kpi,.company,.mini{padding:10px;border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091321)}.kpi span,.sub,.mini span{display:block;color:var(--m);font-size:8px}.kpi b,.mini b{display:block;margin-top:7px;font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card{border:1px solid var(--l);border-radius:14px;background:linear-gradient(180deg,#101c30ed,#08101ded);box-shadow:var(--s);overflow:hidden}.head{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:11px 13px;border-bottom:1px solid var(--l)}.title{font-weight:1000;font-size:13px}.body{padding:10px}.companies{display:grid;grid-template-columns:repeat(4,minmax(300px,1fr));gap:8px;padding:9px}.company{position:relative;overflow:hidden}.company:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--cc,var(--b))}.companyTop{display:flex;justify-content:space-between;gap:7px}.name{font-size:16px;font-weight:1000}.rank{font-size:22px;font-weight:1000;color:var(--y)}.state{display:inline-block;margin-top:5px;padding:3px 6px;border:1px solid #28634f;border-radius:999px;color:var(--g);font-size:8px}.state.off{color:var(--r);border-color:#743746}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.metric{padding:7px;border:1px solid #1d2d45;border-radius:8px;background:#0d192b;min-width:0}.metric span{display:block;color:var(--m);font-size:7px}.metric b{display:block;margin-top:3px;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bar{height:6px;background:#17253b;border-radius:99px;overflow:hidden;margin-top:8px}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.tablewrap{overflow:auto;max-height:720px;overscroll-behavior:contain;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1100px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l);z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.muted{color:var(--m)}.two{display:grid;grid-template-columns:1fr 1fr;gap:11px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.chart{width:100%;height:250px;border:1px solid var(--l);border-radius:10px;background:#050c18}.sw{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:4px}.donuts{display:grid;grid-template-columns:repeat(4,minmax(230px,1fr));gap:10px}.donutCard{padding:10px;border:1px solid var(--l);border-radius:12px;background:#091525}.donut{width:150px;height:150px;margin:8px auto;border-radius:50%;position:relative}.donut:after{content:"";position:absolute;inset:30px;border-radius:50%;background:#091525}.donutTotal{position:absolute;inset:0;z-index:2;display:grid;place-content:center;text-align:center;font-weight:1000;font-size:13px}.donutTotal small{display:block;color:var(--m);font-size:8px}.news{padding:10px;border-bottom:1px solid var(--l)}.news strong{font-size:12px}.log{height:520px;overflow:auto;padding:9px;background:#050a12;font:9px/1.45 Consolas,monospace}.line{display:grid;grid-template-columns:75px 75px 1fr;gap:7px;padding:4px 0;border-bottom:1px dashed #18253a}.empty{padding:22px;text-align:center;color:var(--m)}@media(max-width:1850px){.kpis{grid-template-columns:repeat(5,1fr)}.companies{grid-template-columns:repeat(3,1fr)}.donuts{grid-template-columns:repeat(3,1fr)}}@media(max-width:1300px){.companies{grid-template-columns:repeat(2,1fr)}.two,.three{grid-template-columns:1fr}.donuts{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){body{padding:5px}.top{position:static;flex-direction:column;align-items:flex-start}.status{justify-content:flex-start}.kpis{grid-template-columns:repeat(2,1fr)}.companies,.donuts{grid-template-columns:1fr}}
</style></head><body><div class="shell"><header class="top"><div class="brand">YAZILIM BORSASI V7<small>20.000 müşteri · tick muhasebesi · gerçek kapasite · işletim sistemleri · haberler</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANIYOR</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Müşteri <b id="customers">0</b></span><span class="pill">Gecikme <b id="latency">—</b></span><span id="clock" class="pill">—</span></div></header><div class="ticker"><div id="ticker" class="tickerTrack">Haber bülteni hazırlanıyor…</div></div><nav id="tabs" class="tabs"><button class="tab active" data-view="home">Ana Sayfa</button><button class="tab" data-view="overview">Genel Borsa</button><button class="tab" data-view="charts">Grafikler</button><button class="tab" data-view="systems">İşletim Sistemleri</button><button class="tab" data-view="apps">Uygulamalar</button><button class="tab" data-view="services">Hizmetler</button><button class="tab" data-view="finance">Finans</button><button class="tab" data-view="operations">SLA & Yatırımlar</button><button class="tab" data-view="news">Haber Bülteni</button><button class="tab" data-view="customers">Müşteri CV</button><button class="tab" data-view="security">Risk & Akış</button></nav><main id="home" class="page"></main><main id="overview" class="page" hidden></main><main id="charts" class="page" hidden></main><main id="systems" class="page" hidden></main><main id="apps" class="page" hidden></main><main id="services" class="page" hidden></main><main id="finance" class="page" hidden></main><main id="operations" class="page" hidden></main><main id="news" class="page" hidden></main><main id="customers" class="page" hidden></main><main id="security" class="page" hidden></main></div>
<script>
'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const C=['#42e1a0','#62a8ff','#b58cff','#ffd166','#42d6ee','#ff6b7d','#f58fd6','#8ce99a'];const S={active:'home',loading:false,lastTick:-1,scrollingUntil:0,pending:null,scrolls:new Map(),timer:null};
function view(id){const t=document.getElementById(id)||$('#home');S.active=t.id;$$('.page').forEach(p=>p.hidden=p!==t);$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===t.id));history.replaceState(null,'',`#${t.id}`)}$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){e.preventDefault();view(b.dataset.view)}});
function saveScroll(){S.scrolls.set('window',window.scrollY);$$('[data-scroll-key]').forEach(e=>S.scrolls.set(e.dataset.scrollKey,e.scrollTop))}function restoreScroll(){requestAnimationFrame(()=>{window.scrollTo(0,S.scrolls.get('window')||0);$$('[data-scroll-key]').forEach(e=>{if(S.scrolls.has(e.dataset.scrollKey))e.scrollTop=S.scrolls.get(e.dataset.scrollKey)})})}window.addEventListener('scroll',()=>{S.scrollingUntil=Date.now()+1300;S.scrolls.set('window',window.scrollY)},{passive:true});document.addEventListener('scroll',e=>{const t=e.target;if(t?.dataset?.scrollKey){S.scrollingUntil=Date.now()+1300;S.scrolls.set(t.dataset.scrollKey,t.scrollTop)}},true);
async function req(){const t=performance.now(),r=await fetch(`/api/durum?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const d=await r.json();$('#latency').textContent=`${Math.round(performance.now()-t)} ms`;return d}function poll(){clearInterval(S.timer);S.timer=setInterval(refresh,450)}async function refresh(){if(S.loading)return;S.loading=true;try{const d=await req();const tick=Number(d.motor?.tickNumarasi||0);$('#dot').classList.add('ok');$('#conn').textContent='CANLI';$('#tick').textContent=int(tick);$('#customers').textContent=int(d.genel?.aktifMusteriSayisi);$('#clock').textContent=new Date().toLocaleTimeString('tr-TR');renderTicker(d);if(tick!==S.lastTick){if(Date.now()<S.scrollingUntil){S.pending=d}else{S.pending=null;saveScroll();render(d);restoreScroll();S.lastTick=tick}}else if(S.pending&&Date.now()>=S.scrollingUntil){const p=S.pending;S.pending=null;saveScroll();render(p);restoreScroll();S.lastTick=Number(p.motor?.tickNumarasi||tick)}}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='HATA'}finally{S.loading=false}}
function renderTicker(d){const h=(d.haberBulteni||[]).slice(0,14);$('#ticker').innerHTML=h.length?h.map(x=>`★ T${int(x.tickNumarasi)} · ${esc(x.sirketAdi||'Piyasa')} · ${esc(x.baslik)} — ${esc(x.ozet)}`).join(' &nbsp;&nbsp;&nbsp; ◆ &nbsp;&nbsp;&nbsp; '):'★ Piyasa sakin · Yeni gelişmeler bekleniyor.'}
function companies(d){return(d.sirketler||[]).map(c=>({...c,value:Number(c.isletim?.sirketDegeri||0),users:Number(c.isletim?.toplamAboneSayisi||0),cap:Number(c.v6?.gercekKapasiteBirimi||0),used:Number(c.v6?.kullanilanKapasiteBirimi||0)})).sort((a,b)=>b.value-a.value)}function kpis(d,cs){const g=d.genel||{};return `<section class="kpis">${[['Toplam değer',money(cs.reduce((a,c)=>a+c.value,0))],['Toplam kasa',money(g.toplamSirketKasasi)],['Tick gelir',money(g.toplamTickGeliri)],['Tick gider',money(g.toplamTickGideri)],['Tick net',money(g.toplamTickNeti)],['Toplam borç',money(g.toplamBorc)],['Gerçek kapasite',int(cs.reduce((a,c)=>a+c.cap,0))],['Kullanılan kapasite',int(cs.reduce((a,c)=>a+c.used,0))],['Aktif kullanıcı',int(cs.reduce((a,c)=>a+c.users,0))],['Bağlı şirket',`${int(g.bagliSirketSayisi)}/${int(g.toplamSirketSayisi)}`]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section>`}
function overview(d,cs){return `${kpis(d,cs)}<section class="card"><div class="head"><div><div class="title">ŞİRKET DEĞERİ VE BU TICKİN FİNANSAL SONUCU</div><span class="sub">Gelir, gider ve net yalnız son tamamlanan ticki gösterir; kredi girişi gelir değildir.</span></div></div><div class="companies">${cs.map((c,i)=>{const occ=c.cap?c.used*100/c.cap:0;return `<article class="company" style="--cc:${C[i%C.length]}"><div class="companyTop"><div><div class="name">${esc(c.sirketAdi)}</div><span class="state ${c.bagli?'':'off'}">${c.bagli?'BAĞLI':'KAPALI'}</span></div><div class="rank">#${i+1}</div></div><div class="metrics">${[['Değer',money(c.value)],['Kasa',money(c.kasa)],['Tick gelir',money(c.tickGelir)],['Tick gider',money(c.tickGider)],['Tick net',money(c.tickNetKazanc)],['Borç',money(c.toplamBorc)],['Kredi notu',`${int(c.krediNotu)} ${esc(c.krediSinifi||'')}`],['Kapasite',int(c.cap)],['Kullanım',`%${num(occ)}`],['Kullanıcı',int(c.users)],['Kalite',num(c.kodKalitesiPuani)],['Güvenlik',num(c.guvenlikPuani)]].map(x=>`<div class="metric"><span>${x[0]}</span><b class="${x[0]==='Tick net'?(Number(c.tickNetKazanc)>=0?'good':'bad'):''}">${x[1]}</b></div>`).join('')}</div><div class="bar"><i style="width:${Math.min(100,occ)}%"></i></div></article>`}).join('')}</div></section>`}
function lineChart(rows,key1,key2,key3){if(!rows.length)return'<div class="empty">Henüz grafik verisi yok.</div>';const w=900,h=230,p=25,vals=rows.flatMap(x=>[Number(x[key1]||0),Number(x[key2]||0),Number(x[key3]||0)]),max=Math.max(1,...vals.map(Math.abs)),pts=k=>rows.map((x,i)=>`${p+i*(w-2*p)/Math.max(1,rows.length-1)},${h/2-Number(x[k]||0)*(h/2-p)/max}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="0" y1="${h/2}" x2="${w}" y2="${h/2}" stroke="#33445d"/><polyline fill="none" stroke="${C[0]}" stroke-width="3" points="${pts(key1)}"/><polyline fill="none" stroke="${C[5]}" stroke-width="3" points="${pts(key2)}"/><polyline fill="none" stroke="${C[1]}" stroke-width="3" points="${pts(key3)}"/></svg>`}
function charts(d,cs){const financeCards=cs.map((c,i)=>{const rows=(c.finansGecmisi||[]).slice(-60);return `<div class="card"><div class="head"><div><div class="title">${esc(c.sirketAdi)} · GELİR/GİDER/NET</div><span class="sub">Son ${rows.length} tick</span></div></div><div class="body">${lineChart(rows,'toplamGelir','toplamGider','tickNetKazanc')}<div class="legend"><span><i class="sw" style="background:${C[0]}"></i>Gelir</span><span><i class="sw" style="background:${C[5]}"></i>Gider</span><span><i class="sw" style="background:${C[1]}"></i>Net</span></div></div></div>`}).join('');const donuts=(d.kategoriPazarPaylari||[]).slice(0,12).map((k,ki)=>{let acc=0;const parts=(k.uygulamalar||[]).map((u,i)=>{const a=acc;acc+=Number(u.payYuzdesi||0);return `${C[i%C.length]} ${a}% ${acc}%`}).join(',');return `<div class="donutCard"><b>${esc(k.kategori)}</b><div class="donut" style="background:conic-gradient(${parts||'#24364f 0 100%'})"><div class="donutTotal">${int(k.toplamKullanici)}<small>kullanıcı</small></div></div>${(k.uygulamalar||[]).slice(0,6).map((u,i)=>`<div class="row"><span><i class="sw" style="background:${C[i%C.length]}"></i>${esc(u.uygulamaAdi)}</span><b>%${num(u.payYuzdesi)}</b></div>`).join('')}</div>`}).join('')||'<div class="empty">Aktif uygulama pazarı oluşmadı.</div>';return `<section class="two">${financeCards}</section><section class="card"><div class="head"><div><div class="title">KATEGORİ BAZLI UYGULAMA PAZAR PAYLARI</div><span class="sub">Aktif kullanıcıların kategori içindeki uygulama dağılımı.</span></div></div><div class="body donuts">${donuts}</div></section>`}
function systems(d){const rows=(d.uygulamaPiyasasi||[]).filter(x=>(x.uygulama?.urunTuru||x.urun?.urunTuru)==='isletim-sistemi');return `<section class="card"><div class="head"><div class="title">İŞLETİM SİSTEMİ PAZARI</div></div><div class="tablewrap" data-scroll-key="systems"><table><thead><tr><th>Şirket</th><th>Sistem</th><th>Protokoller</th><th class="num">Müşteri</th><th class="num">Kapasite</th><th class="num">Kalite</th><th>Durum</th></tr></thead><tbody>${rows.map(x=>{const a=x.uygulama||{},u=x.urun||{};return `<tr><td><b>${esc(x.sirketAdi)}</b></td><td><b>${esc(a.uygulamaAdi)}</b><div class="muted">${esc(a.uygulamaKimligi)}</div></td><td>${(a.desteklenenProtokoller||[]).map(p=>`<span class="tag">${esc(p)}</span>`).join(' ')}</td><td class="num">${int(x.gercekIsletimSistemiMusterisi||u.aktifKullaniciSayisi)}</td><td class="num">${int(u.kullaniciKapasitesi)}</td><td class="num">${num(u.urunKalitesi)}</td><td class="${x.piyasada&&u.aktif?'good':'bad'}">${x.piyasada&&u.aktif?'AKTİF':'PASİF'}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Aktif işletim sistemi yok.</td></tr>'}</tbody></table></div></section>`}
function apps(d){const rows=(d.uygulamaPiyasasi||[]).filter(x=>(x.uygulama?.urunTuru||x.urun?.urunTuru)!=='isletim-sistemi');return `<section class="card"><div class="head"><div class="title">UYGULAMALAR VE ABONELİK PAZARI</div></div><div class="tablewrap" data-scroll-key="apps"><table><thead><tr><th>Şirket</th><th>Uygulama</th><th>Kategori</th><th>Platform</th><th class="num">Fiyat</th><th class="num">Kullanıcı</th><th class="num">Kapasite</th><th class="num">Kalite</th><th>Durum</th></tr></thead><tbody>${rows.map(x=>{const a=x.uygulama||{},u=x.urun||{};return `<tr><td><b>${esc(x.sirketAdi)}</b></td><td><b>${esc(a.uygulamaAdi)}</b><div class="muted">${esc(a.uygulamaKimligi)}</div></td><td>${esc(a.kategori)}</td><td>${(a.desteklenenPlatformlar||[]).map(p=>`<span class="tag">${esc(p)}</span>`).join(' ')}</td><td class="num">${money(u.abonelikUcreti)}</td><td class="num">${int(u.aktifKullaniciSayisi)}</td><td class="num">${int(u.kullaniciKapasitesi)}</td><td class="num">${num(u.urunKalitesi)}</td><td class="${x.piyasada&&u.aktif?'good':'bad'}">${x.piyasada&&u.aktif?'AKTİF':'PASİF'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Aktif uygulama yok.</td></tr>'}</tbody></table></div></section>`}
function services(d){const rows=d.hizmetPiyasasi||[];return `<section class="card"><div class="head"><div><div class="title">500 STANDART HİZMET PAZARI</div><span class="sub">Scroll sırasında panel yeniden çizilmez; bulunduğunuz satır korunur.</span></div></div><div class="tablewrap" data-scroll-key="services"><table><thead><tr><th>Hizmet</th><th>Açıklama</th><th class="num">Talep</th><th class="num">Bütçe</th><th class="num">Sağlayıcı</th><th>Sağlayıcılar</th></tr></thead><tbody>${rows.map(h=>`<tr><td><b>${esc(h.hizmetKimligi)}</b><div class="muted">v${esc(h.hizmetSurumu)}</div></td><td>${esc(h.aciklama)}</td><td class="num">${int(h.talepSayisi)}</td><td class="num">${money(h.toplamTalepButcesi)}</td><td class="num">${int(h.saglayiciSayisi)}</td><td>${(h.saglayicilar||[]).map(s=>`<span class="tag ${s.bagli?'good':'bad'}">${esc(s.sirketAdi)} · ${money(s.birimFiyat)} · K${int(s.azamiEszamanliIs)}</span>`).join(' ')||'<span class="bad">Sağlayıcı yok</span>'}</td></tr>`).join('')}</tbody></table></div></section>`}
function finance(d,cs){return `<section class="card"><div class="head"><div><div class="title">ŞİRKETLERİN BU TICK GELİR–GİDER TABLOSU</div><span class="sub">Tarihsel toplam değil, son tamamlanan tick. Kurtarma kredisi ayrı gösterilir.</span></div></div><div class="tablewrap" data-scroll-key="finance"><table><thead><tr><th>Şirket</th><th class="num">Gelir</th><th class="num">Gider</th><th class="num">Net</th><th class="num">Kurtarma</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Kredi notu</th><th class="num">Değer</th></tr></thead><tbody>${cs.map(c=>`<tr><td><b>${esc(c.sirketAdi)}</b></td><td class="num good">${money(c.tickGelir)}</td><td class="num bad">${money(c.tickGider)}</td><td class="num ${Number(c.tickNetKazanc)>=0?'good':'bad'}"><b>${money(c.tickNetKazanc)}</b></td><td class="num warn">${money(c.kurtarmaKredisi)}</td><td class="num">${money(c.kasa)}</td><td class="num">${money(c.toplamBorc)}</td><td class="num">${int(c.krediNotu)} ${esc(c.krediSinifi||'')}</td><td class="num">${money(c.value)}</td></tr>`).join('')}</tbody></table></div></section>${charts(d,cs)}`}
function operations(d){return `<section class="two"><div class="card"><div class="head"><div class="title">SLA SÖZLEŞMELERİ</div></div><div class="body">${(d.sozlesmePiyasasi||[]).map(x=>{const s=x.sozlesme||{};return `<div class="mini"><b>${esc(x.sirketAdi)} · ${esc(s.baslik)}</b><span>Başarı ${int(s.basariliTickSayisi)} · İhlal ${int(s.ihlalSayisi)} · Bitiş T${int(s.bitisTicki)}</span></div>`}).join('')||'<div class="empty">Aktif sözleşme yok.</div>'}</div></div><div class="card"><div class="head"><div class="title">YATIRIM SEVİYELERİ</div></div><div class="body">${(d.yatirimPiyasasi||[]).map(x=>`<div class="row mini"><span>${esc(x.sirketAdi)} · ${esc(x.yatirimTuru)}</span><b>${int(x.seviye)}</b></div>`).join('')}</div></div></section>`}
function news(d){const h=d.haberBulteni||[];return `<section class="card"><div class="head"><div><div class="title">YAZILIM PİYASASI HABER BÜLTENİ</div><span class="sub">Finansal alarm, kurtarma kredisi, kapasite, yatırım ve uygulama olayları.</span></div></div><div class="body">${h.map(x=>`<article class="news"><div class="row"><strong class="${x.seviye==='kritik'||x.onem==='kritik'?'bad':x.seviye==='iyi'||x.onem==='iyi'?'good':'warn'}">${esc(x.baslik)}</strong><span>T${int(x.tickNumarasi)} · ${esc(x.sirketAdi||'Piyasa')}</span></div><p>${esc(x.ozet)}</p>${Number(x.finansalEtki)?`<b class="${Number(x.finansalEtki)>=0?'good':'bad'}">${money(x.finansalEtki)}</b>`:''}</article>`).join('')||'<div class="empty">Haber yok.</div>'}</div></section>`}
function customers(d){const rows=d.musteriCvOrnekleri||[];return `<section class="card"><div class="head"><div><div class="title">MÜŞTERİ CV ÖRNEKLERİ</div><span class="sub">20.000 müşterinin kalıcı işletim sistemi, uygulama ve harcama geçmişinden örneklem.</span></div></div><div class="tablewrap" data-scroll-key="customers"><table><thead><tr><th>Müşteri</th><th>Tür</th><th>Meslek</th><th>Gelir</th><th>İşletim sistemi</th><th>Uygulamalar</th><th class="num">Harcama</th><th class="num">Başarılı iş</th><th class="num">Başarısız iş</th></tr></thead><tbody>${rows.map(m=>`<tr><td><b>${esc(m.musteriAdi)}</b><div class="muted">${esc(m.musteriKimligi)}</div></td><td>${esc(m.musteriTuru)}</td><td>${esc(m.meslekProfili)}</td><td>${esc(m.gelirSegmenti)}</td><td>${esc(m.isletimSistemiKimligi||'bekliyor')}</td><td>${(m.uygulamalar||[]).map(a=>`<span class="tag">${esc(a)}</span>`).join(' ')}</td><td class="num">${money(m.toplamHarcama)}</td><td class="num">${int(m.basariliIs)}</td><td class="num">${int(m.basarisizIs)}</td></tr>`).join('')}</tbody></table></div></section>`}
function security(d,cs){const logs=d.olaylar||[];return `<section class="two"><div class="card"><div class="head"><div class="title">RİSK VE GÜVENLİK SIRALAMASI</div></div><div class="body">${[...cs].sort((a,b)=>Number(b.guvenlikPuani)-Number(a.guvenlikPuani)).map((c,i)=>`<div class="row mini"><span>#${i+1} ${esc(c.sirketAdi)}</span><span>Güvenlik <b>${num(c.guvenlikPuani)}</b> · Engellenen ${int(c.engellenenSaldiriSayisi)} · Başarılı saldırı ${int(c.basariliSaldiriSayisi)}</span></div>`).join('')}</div></div><div class="card"><div class="head"><div class="title">CANLI MOTOR AKIŞI</div></div><div class="log" data-scroll-key="logs">${logs.map(x=>`<div class="line"><span>${esc(x.zaman||'')}</span><b>${esc(x.seviye||'')}</b><span>${esc(x.mesaj||x.aciklama||'')}</span></div>`).join('')}</div></div></section>`}
function render(d){const cs=companies(d),o=overview(d,cs),ch=charts(d,cs),sy=systems(d),ap=apps(d),sv=services(d),fi=finance(d,cs),op=operations(d),nw=news(d),cu=customers(d),se=security(d,cs);$('#overview').innerHTML=o;$('#charts').innerHTML=ch;$('#systems').innerHTML=sy;$('#apps').innerHTML=ap;$('#services').innerHTML=sv;$('#finance').innerHTML=fi;$('#operations').innerHTML=op;$('#news').innerHTML=nw;$('#customers').innerHTML=cu;$('#security').innerHTML=se;$('#home').innerHTML=[o,ch,sy,ap,sv,fi,op,nw,cu,se].join('');view(S.active)}
view(location.hash.slice(1)||'home');refresh().then(poll);setInterval(()=>{$('#clock').textContent=new Date().toLocaleTimeString('tr-TR')},1000);
</script></body></html>
""";
}
